-- ============================================================================
-- EC7: Petroleum Industry Act 2021 & Nigerian Fiscal Terms joins the
-- catalogue in the Economics & Commercial module. AN ENGINE COURSE: there is no
-- Suite app; the practicals run in the course's own calculator panels.
--
-- Catalogue row (module 'economics'; path_order 72; prereq_slug NULL,
-- the lead's decision; school left at its default) plus the three capstones and
-- their eighteen graded fields, generated by tools/course-waves/pia/gen_course.py
-- from the ENGINE'S OWN RUN (pia_capstone.mjs through the vendored
-- engines/economics/cashflow.ts 3.12.0), which it refuses to write unless
-- fields.json carries exactly that run's values and the tolerance
-- gradedTolerance.js derives. Deep seeds are three separate migrations; the
-- go-live is a fifth and is HELD until a NextGen production upload carries the
-- route /dashboard/apps/pia.
--
-- WHAT IS GRADED. ODOZI (Associate) grades a weighted royalty rate, a
-- production royalty, a hydrocarbon tax, a development levy, companies income
-- tax over the life and the government take; NKEMDI (Professional) grades a
-- liquids royalty, a production allowance across the new-lease cap, a
-- hydrocarbon tax chargeable profit, a cost price ratio carry, the cost
-- forfeited at cessation and companies income tax; ALAKU (Expert) grades a
-- total royalty, a chargeable profit in the first NTA year, the tertiary
-- education tax, the development levy and companies income tax with the escrow
-- condition not met. Every value is a return value of the engine, identical
-- under every open reading of the texts, and the data it was run on is in the
-- case file the prompt names.
-- ============================================================================

insert into public.academy_apps (slug, name, module, path_order, status, prereq_slug)
values ('pia', 'Petroleum Industry Act 2021 & Nigerian Fiscal Terms', 'economics', 72, 'coming_soon', null)
on conflict (slug) do nothing;

insert into public.academy_capstones
    (app_slug, tier, cert_tier, dataset, title, prompt, fields)
values
(
  'pia', 'beginner', 'associate',
  'ODOZI, an onshore lease converted from an oil mining lease, 2027 to 2032',
  'The map of the Act on one ledger',
  'ODOZI, an Ekene synthetic onshore lease converted from an oil mining lease. One case file comes with this capstone: odozi_case.json carries the terms (cfg) and the production, capex and opex rows the engine ran, 2027 to 2032; paste it into the ledger view of the calculator. The terms: terrain onshore, licence PML, lease converted, no converted marginal field; a 60 percent working interest, and every money value is at that share; oil at 54 USD/bbl, gas at 2.8 USD/Mscf, every price flat; opex escalating at 2 percent a year from 2027; 40 percent of the gas used in-country; prior-year opex of 19000000 USD for the first year''s HCDT; 0 bbl produced before the ledger; the framework override auto, so each year is read under the law of its own year. Every other term is the engine''s default, which follows the texts: companies income tax at 30 percent, the NDDC levy at 3 percent of the total annual budget, the capital allowance over the five years the texts fix, the cost price ratio limit of 65 percent, the Sixth Schedule production allowance, and the tertiary education tax at its statutory rate. The royalty by price is read on the Petroleum Royalty Regulations 2022 base (the engine default). Report six values: the crude oil and condensate production royalty rate in 2028, as a fraction; the production royalty on liquids and gas in 2029; the hydrocarbon tax in 2030; the development levy in 2031; companies income tax over the life of the ledger; and the government take, undiscounted, in percent. All six to six decimals.',
  jsonb_build_array(
    jsonb_build_object('key','odozi_2028_liquids_royalty_rate', 'label','The crude oil and condensate production royalty rate in 2028', 'unit','fraction', 'expected',0.05886243386243386, 'tol',5e-07),
    jsonb_build_object('key','odozi_2029_production_royalty_usd', 'label','The production royalty on liquids and gas in 2029, at your share', 'unit','USD', 'expected',4824771.4799999995, 'tol',5e-07),
    jsonb_build_object('key','odozi_2030_hct_usd', 'label','The hydrocarbon tax in 2030, at your share', 'unit','USD', 'expected',13491169.608103443, 'tol',5e-07),
    jsonb_build_object('key','odozi_2031_dev_levy_usd', 'label','The development levy in 2031, at your share', 'unit','USD', 'expected',2038747.0449887998, 'tol',5e-07),
    jsonb_build_object('key','odozi_total_cit_usd', 'label','Companies income tax over the life of the ledger, at your share', 'unit','USD', 'expected',101420921.54433312, 'tol',5e-07),
    jsonb_build_object('key','odozi_government_take_pct', 'label','The government take, undiscounted', 'unit','percent', 'expected',65.07108427930685, 'tol',5e-07)
  )
),
(
  'pia', 'intermediate', 'professional',
  'NKEMDI, a shallow water lease granted out of new acreage, 2027 to 2033',
  'The hydrocarbon tax as a system',
  'NKEMDI, an Ekene synthetic shallow water lease granted out of new acreage. One case file comes with this capstone: nkemdi_case.json carries the terms (cfg) and the production, capex and opex rows the engine ran, 2027 to 2033; paste it into the ledger view of the calculator. The terms: terrain shallow_water, licence PML, lease new, no converted marginal field; a 45 percent working interest, and every money value is at that share; oil at 54 USD/bbl, condensate at 51 USD/bbl, gas at 3.1 USD/Mscf, every price flat; opex escalating at 0 percent a year from 2027; 25 percent of the gas used in-country; prior-year opex of 160000000 USD for the first year''s HCDT; 64500000 bbl produced before the ledger; the framework override auto, so each year is read under the law of its own year. Every other term is the engine''s default, which follows the texts: companies income tax at 30 percent, the NDDC levy at 3 percent of the total annual budget, the capital allowance over the five years the texts fix, the cost price ratio limit of 65 percent, the Sixth Schedule production allowance, and the tertiary education tax at its statutory rate. The royalty by price is read on the Petroleum Royalty Regulations 2022 base (the engine default). The texts do not say which hydrocarbon tax rate a petroleum mining lease granted out of new acreage onshore or in shallow water pays, so this capstone states 30 percent as a stated reading; none of the six values depends on it. Report six values: the crude oil and condensate production royalty in 2028; the production allowance in 2029; the hydrocarbon tax chargeable profit in 2029; the cost the cost price ratio carries out of 2031 into 2032; the cost forfeited when the ledger ends; and companies income tax over the life of the ledger. All six to six decimals.',
  jsonb_build_array(
