    jsonb_build_object('key','nkemdi_2029_hct_chargeable_profit_usd', 'label','The hydrocarbon tax chargeable profit in 2029, at your share', 'unit','USD', 'expected',62018258.59948723, 'tol',5e-07),
    jsonb_build_object('key','nkemdi_2031_cpr_deferred_usd', 'label','The cost the cost price ratio carries out of 2031, at your share', 'unit','USD', 'expected',70390530.68609568, 'tol',5e-07),
